import React, { useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import ContactBar from './components/ContactBar';
import About from './components/About';
import Education from './components/Education';
import Skills from './components/Skills';
import Projects from './components/Projects';
import Internship from './components/Internship';
import Certifications from './components/Certifications';
import Achievements from './components/Achievements';
import ContactForm from './components/ContactForm';
import Footer from './components/Footer';

const App: React.FC = () => {
  useEffect(() => {
    // Function to reveal elements
    const revealElements = () => {
      const observerOptions = {
        root: null,
        rootMargin: '0px 0px -5% 0px',
        threshold: 0.01 // Minimal threshold for instant response
      };

      const handleIntersect = (entries: IntersectionObserverEntry[]) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      };

      const observer = new IntersectionObserver(handleIntersect, observerOptions);
      const targets = document.querySelectorAll('.reveal');
      targets.forEach(target => observer.observe(target));

      return observer;
    };

    const observer = revealElements();

    // Direct fix for anchor navigation: Reveal everything in the target section immediately
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash) {
        const targetId = hash.substring(1);
        const targetElement = document.getElementById(targetId);
        if (targetElement) {
          // Find all revealable children within the target section and activate them
          const childReveals = targetElement.querySelectorAll('.reveal');
          childReveals.forEach(el => el.classList.add('active'));
          // Also check if the section itself is a reveal element
          if (targetElement.classList.contains('reveal')) {
            targetElement.classList.add('active');
          }
        }
      }
    };

    // Listen for hash changes
    window.addEventListener('hashchange', handleHashChange);

    // Also intercept clicks on internal links to handle cases where hash doesn't "change" (e.g. clicking same link twice)
    const handleInternalClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const link = target.closest('a');
      if (link && link.hash && link.origin === window.location.origin) {
        // Delay slightly to allow the browser to start the scroll, then force reveal
        setTimeout(handleHashChange, 50);
      }
    };
    document.addEventListener('click', handleInternalClick);

    // Run once on load for initial hash
    setTimeout(handleHashChange, 500);

    return () => {
      observer.disconnect();
      window.removeEventListener('hashchange', handleHashChange);
      document.removeEventListener('click', handleInternalClick);
    };
  }, []);

  return (
    <div className="min-h-screen font-sans bg-cream selection:bg-ochre/30">
      <Navbar />
      <main>
        <Hero />
        <ContactBar />
        <About />
        <Education />
        <Skills />
        <Projects />
        <Internship />
        <Certifications />
        <Achievements />
        <ContactForm />
      </main>
      <Footer />
    </div>
  );
};

export default App;

