import React, { useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Projects from './components/Projects';
import Internship from './components/Internship';
import ContactForm from './components/ContactForm';

const App: React.FC = () => {
  useEffect(() => {
    // Reveal logic to handle scroll animations
    const revealElements = () => {
      const observerOptions = {
        root: null,
        rootMargin: '0px 0px -10% 0px',
        threshold: 0.1
      };

      const handleIntersect = (entries: IntersectionObserverEntry[]) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      };

      const observer = new IntersectionObserver(handleIntersect, observerOptions);
      const targets = document.querySelectorAll('.reveal');
      targets.forEach(target => observer.observe(target));

      return observer;
    };

    const observer = revealElements();

    // Force reveal when navigating via anchor links
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash) {
        const targetId = hash.substring(1);
        const targetElement = document.getElementById(targetId);
        if (targetElement) {
          const childReveals = targetElement.querySelectorAll('.reveal');
          childReveals.forEach(el => el.classList.add('active'));
          if (targetElement.classList.contains('reveal')) {
            targetElement.classList.add('active');
          }
        }
      }
    };

    window.addEventListener('hashchange', handleHashChange);

    // Initial check for hash on load
    setTimeout(handleHashChange, 500);

    return () => {
      observer.disconnect();
      window.removeEventListener('hashchange', handleHashChange);
    };
  }, []);

  return (
    <div className="min-h-screen font-sans bg-cream selection:bg-ochre/30">
      <Navbar />
      <main>
        <Hero />
        <About />
        <Projects />
        <Internship />
        <ContactForm />
      </main>
    </div>
  );
};

